import { createForks, teardownForks, createWorkspace, teardownWorkspace, Forks, Workspace } from "@tigrisdata/agent-kit";
import { S3Client, GetObjectCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import fs from "fs/promises";

const config = {
  accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID,
  secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY,
  endpoint: "https://t3.storage.dev",
};

async function main() {
  const forksResponse = await createForks("gold-eval-dataset", 3, {
    prefix: "eval-attempt",
    credentials: { role: "ReadOnly" },
    config
  });

  if (forksResponse.error) {
    throw forksResponse.error;
  }

  const forks: Forks = forksResponse.data;
  const workspaces: { workspace: Workspace; forkBucket: string }[] = [];

  try {
    await Promise.all(
      forks.forks.map(async (fork, i) => {
        const workspaceName = `eval-writer-${i}`;
        const workspaceResponse = await createWorkspace(workspaceName, {
          credentials: { role: "Editor" },
          config,
        });

        if (workspaceResponse.error) {
          throw workspaceResponse.error;
        }

        const workspace: Workspace = workspaceResponse.data;
        workspaces.push({ workspace, forkBucket: fork.bucket });

        const forkS3 = new S3Client({
          endpoint: "https://t3.storage.dev",
          region: "auto",
          credentials: {
            accessKeyId: fork.credentials!.accessKeyId,
            secretAccessKey: fork.credentials!.secretAccessKey,
          },
        });

        const workspaceS3 = new S3Client({
          endpoint: "https://t3.storage.dev",
          region: "auto",
          credentials: {
            accessKeyId: workspace.credentials!.accessKeyId,
            secretAccessKey: workspace.credentials!.secretAccessKey,
          },
        });

        const prompts = ["p1.json", "p2.json", "p3.json"];

        for (const prompt of prompts) {
          const getObj = await forkS3.send(
            new GetObjectCommand({
              Bucket: fork.bucket,
              Key: `prompts/${prompt}`,
            })
          );

          const body = await getObj.Body?.transformToString();
          if (body === undefined) throw new Error(`Empty body for ${prompt}`);

          const reversed = body.split("").reverse().join("");
          const answerKey = `answers/${prompt.replace(".json", ".txt")}`;

          await workspaceS3.send(
            new PutObjectCommand({
              Bucket: workspace.bucket,
              Key: answerKey,
              Body: reversed,
            })
          );
        }
      })
    );

    // After all three attempts finish, fetch every answer back and aggregate
    const aggregated: Record<string, Record<string, string>> = {};

    for (const { workspace, forkBucket } of workspaces) {
      const workspaceS3 = new S3Client({
        endpoint: "https://t3.storage.dev",
        region: "auto",
        credentials: {
          accessKeyId: workspace.credentials!.accessKeyId,
          secretAccessKey: workspace.credentials!.secretAccessKey,
        },
      });

      const results: Record<string, string> = {};
      const prompts = ["p1", "p2", "p3"];

      for (const p of prompts) {
        const getObj = await workspaceS3.send(
          new GetObjectCommand({
            Bucket: workspace.bucket,
            Key: `answers/${p}.txt`,
          })
        );
        const body = await getObj.Body?.transformToString();
        if (body === undefined) throw new Error(`Empty body for answer ${p} in ${workspace.bucket}`);
        results[p] = body;
      }

      aggregated[forkBucket] = results;
    }

    await fs.writeFile(
      "/home/user/orchestrator/aggregated.json",
      JSON.stringify(aggregated, null, 2)
    );
  } finally {
    // Teardown everything even on failure
    for (const { workspace } of workspaces) {
      await teardownWorkspace(workspace, { config }).catch((err) =>
        console.error(`Failed to teardown workspace ${workspace.bucket}:`, err)
      );
    }
    if (forks) {
      await teardownForks(forks, { config }).catch((err) =>
        console.error(`Failed to teardown forks:`, err)
      );
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

